INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(275, 'koKR', 'Wrzody na ziemi', 'Nie wiem dlaczego, ale na Bagniskach coś się jątrzy. Powstały pełzacze trzęsawisk. To chore, rozpalone gorączką wrzody na ciele tej ziemi – by gorączka ustąpiła, trzeba je unicestwić i pozwolić im na powrót spocząć w moczarach.$B$BPełzacze trzęsawisk snują się wśród wodnych szlaków Bagnisk.', 'Zabij 8 pełzaczy trzęsawisk, a następnie wróć do Rethiela Strażnika Zieleni na Bagniskach.', '', 'Wróć do Rethiela Strażnika Zieleni na Zielonym Pasie na Bagniskach.', '', '', '', '', 0),
(276, 'koKR', 'Tratujące łapy', 'Gnole z Mchoskórych od wielu lat żyły na Bagniskach w spokoju, lecz teraz jest ich coraz więcej. Ich stopy tratują krzewy i kwiaty trzęsawisk, a ich plugawe topory ścinają zbyt wiele drzew na opał.$B$BNie żyją już w zgodzie z ziemią. Aby Bagniska przetrwały, trzeba przetrzebić gnole.$B$BZabij 15 gnoli z Mchoskórych i 10 kundli z Mchoskórych. Poluj na nie na południu, w pobliżu krasnoludzkiej Bramy Algaz. Gdy to zrobisz, wróć do mnie.', 'Zabij 15 gnoli z Mchoskórych i 10 kundli z Mchoskórych, a następnie wróć do Rethiela Strażnika Zieleni na Bagniskach.', '', 'Wróć do Rethiela Strażnika Zieleni na Zielonym Pasie na Bagniskach.', '', '', '', '', 0),
(277, 'koKR', 'Ogniste tabu', 'Mchoskórzy ścinają drzewa Bagnisk i palą ich ciało, by się ogrzać. Dłużej nie zniosę tego bólu!$B$BOdbierz Mchoskórym ich surowe krzemienie – narzędzia, którymi rozniecają ogień. Krzemienie noszą przy sobie wszyscy Mchoskórzy prócz mniejszych gnoli z Mchoskórych i kundli z Mchoskórych.', 'Przynieś Rethielowi Strażnikowi Zieleni 9 surowych krzemieni.', '', 'Wróć do Rethiela Strażnika Zieleni na Zielonym Pasie na Bagniskach.', '', '', '', '', 0),
(279, 'koKR', 'Szpony z głębin', 'Murloki wypełzają z głębokich wód i budują swoje wioski na wybrzeżu. Nękają naszych rybaków i kupców – trzeba je powstrzymać.$B$BJeden z tych murloków, Żarłok, czai się wśród innych modroskrzelich murloków i napada na kupców na drodze, a potem zawsze chowa się w pobliskich murlocich lepiankach. Nasi kupcy są w niebezpieczeństwie, a my zapłacimy za ich ochronę.$B$BŻarłok grasuje przy ujściu rzeki na północ stąd. Znajdź go, wybij jego pobratymców i przynieś mi jego głowę.', 'Zabij 12 modroskrzelich murloków.$B$BZabij Żarłoka i zabierz jego głowę.$B$BPrzynieś głowę Żarłoka Karlowi Boranowi w Przystani Menethilów.', '', 'Wróć do Karla Borana w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(281, 'koKR', 'Odzyskiwanie towarów', 'Niedawno murloki napadły na statek handlowy „Ślepa Księżniczka”. Statek wyszedł z tego cało, ale stwory wciągnęły za burtę dużą część ładunku, w tym bardzo cenny posążek Terenasa Menethila. Chcemy go odzyskać.$B$BPrzeszukaj nadbrzeżne lepianki murloków w poszukiwaniu skrzyń, beczek i innych śladów zaginionego ładunku. Znajdź posążek Menethilów i przynieś mi go.', 'Przeszukaj skrzynie i beczki w nadbrzeżnych obozach murloków.', '', '', '', '', '', '', 0),
(284, 'koKR', 'Poszukiwania trwają', 'Dokładnie przeszukujesz to skupisko murlocich lepianek, ale nie znajdujesz śladu posążka Menethilów.$B$BMoże w jednej z dwóch pobliskich lepianek, na północy i północnym wschodzie, będzie więcej wskazówek.', 'Odszukaj posążek Menethilów.', '', '', '', '', '', '', 0),
(285, 'koKR', 'Przeszukaj kolejne lepianki', 'Dokładne oględziny tego skupiska murlocich lepianek nic nie dają.$B$B...ale masz pewność, że następny trop okaże się owocny.$B$BW którejś z lepianek na północy musi być posążek Menethilów!', 'Przeszukuj dalej murlocie lepianki w poszukiwaniu posążka Menethilów.', '', '', '', '', '', '', 0),
(286, 'koKR', 'Zwrot posążka', 'Gdy wyciągasz beczkę z błota i ją otwierasz, znajdujesz srebrzystą figurkę owiniętą w delikatną słomę. Przedstawia młodego, długowłosego paladyna z uniesionym młotem.$B$BTo musi być posążek Menethilów! Teraz musisz go zanieść Karlowi Boranowi w Przystani Menethilów.', 'Przynieś posążek Menethilów Karlowi Boranowi w Przystani Menethilów na Bagniskach.', '', '', '', '', '', '', 0),
(288, 'koKR', 'Trzecia Flota', 'Byłem kiedyś pierwszym oficerem na „Pani Fal”, okręcie liniowym Trzeciej Floty Kul Tiras. Przeklętej Floty. Przeklętej, bo w swoim ostatnim rejsie flotę zaatakowały czerwone smoki. Smoki, którymi władali orkowie!$B$BNie mieliśmy szans z tym smoczym ogniem... Naszą flotę spalono i zatopiono u tego tu wybrzeża. Jestem jedynym, kto ocalał z tych nieszczęsnych okrętów...$B$B...Och, jak mi łupie i wali w głowie! Muszę się czegoś napić, jeśli mam poskromić tego kaca i opowiadać dalej.', 'Kup pierwszemu oficerowi Fitzsimmonsowi dzban miodu pitnego.', '', 'Wróć do pierwszego oficera Fitzsimmonsa w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(289, 'koKR', 'Przeklęta załoga', '<Pokrzepiony Fitzsimmons ciągnie swoją opowieść...>$B$BJestem jedynym ocalałym z nieszczęsnej Trzeciej Floty Kul Tiras, która rozbiła się u wybrzeży na północy. Ale choć tylko ja z całej floty jeszcze oddycham, nie tylko ja wciąż chodzę po świecie! Na jednym z naszych okrętów ukryto bowiem wielki i straszliwy skarb, a jego upiorna moc więzi dusze moich braci w gnijących kadłubach.$B$BJeśli jednak uwolnisz choć kilku moich braci, może zdołasz zdjąć z nich klątwę.', 'Zabij 13 przeklętych marynarzy, 5 przeklętych piechurów morskich i pierwszego oficera Snelliga. Przynieś tabakierkę Snelliga pierwszemu oficerowi Fitzsimmonsowi w Przystani Menethilów.', '', 'Wróć do pierwszego oficera Fitzsimmonsa w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(290, 'koKR', 'Zdjęcie klątwy', 'Aby zdjąć klątwę i uwolnić wszystkich moich braci, trzeba odzyskać i oczyścić to... coś... ukryte na moim okręcie! Nie wiem, co to było, ale wiem, że trzymano to pod kluczem w okrętowej szkatule, której pilnował kapitan Halyndor.$B$BMój dawny kapitan wciąż nawiedza moje sny. Wiem, że krąży po moim zgubionym okręcie, „Nieustraszonym”. Zdobądź od niego klucz i otwórz nim szkatułę z „Nieustraszonego”.$B$BA kiedy już zdobędziesz to przeklęte coś, zanieś je kapłanowi Glorinowi Stalobrwemu w mieście.', 'Zdobądź od kapitana Halyndora klucz do szkatuły z „Nieustraszonego”.$B$BOtwórz tym kluczem zamkniętą szkatułę z „Nieustraszonego”.', '', 'Odszukaj zamkniętą szkatułę z „Nieustraszonego” na Bagniskach.', '', '', '', '', 0),
(292, 'koKR', 'Oko Paletha', 'W skrzyni leży poczerniała kula pulsująca upiornym światłem. To skarb, o którym mówił Fitzsimmons: przeklęte oko Paletha.$B$BZanieś przeklęte oko Paletha krasnoludzkiemu kapłanowi Glorinowi Stalobrwemu w Przystani Menethilów. Zapytaj go, jak zdjąć z oka klątwę.', 'Przynieś przeklęte oko Paletha Glorinowi Stalobrwemu w Przystani Menethilów na Bagniskach.', '', '', '', '', '', '', 0),
(294, 'koKR', 'Zemsta Ormera', 'Sytuacja jest poważna, co do tego nie ma wątpliwości. Kiedy odkopaliśmy te kości, zwabiły tu raptory. Te plugawe bestie wybiły moich braci, a mnie, Merrin i biednego poszukiwacza uwięziły tu na górze.$b$bPomóż oczyścić Bagniska z tych raptorów, $N. Cętkowane raptory i cętkowane skrzekacze są tuż na zachód od tamtego urwiska. Zabij po 10 z każdego rodzaju, jeśli dasz radę.$b$bTo będzie dobry początek zemsty, jaką dla nich szykuję.', 'Ormer Żelaznowarkoczy na Wykopaliskach Whelgara chce, żebyś $gzabił:zabiła; 10 cętkowanych skrzekaczy i 10 cętkowanych raptorów.', '', 'Wróć do Ormera Żelaznowarkoczego na Wykopaliskach Whelgara na Bagniskach.', '', '', '', '', 0),
(295, 'koKR', 'Zemsta Ormera', 'Teraz czas, żeby te przeklęte raptory naprawdę pożałowały swojej żądzy krwi. Tam w dole roi się od cętkowanych kosopazurów i cętkowanych brzytwopaszczych. Niech te parszywe stwory zapłacą – zabij po 10 z każdego rodzaju!', 'Ormer Żelaznowarkoczy chce, żebyś $gzabił:zabiła; 10 cętkowanych kosopazurów i 10 cętkowanych brzytwopaszczych, a potem $gwrócił:wróciła; do niego na Wykopaliska Whelgara.', '', 'Wróć do Ormera Żelaznowarkoczego na Wykopaliskach Whelgara na Bagniskach.', '', '', '', '', 0),
(296, 'koKR', 'Zemsta Ormera', 'Kiedy $gbyłeś:byłaś; tam na dole, zauważyłem, że jeden z tych stworów odstaje od reszty. Większy i groźniejszy. Założę się, że to on przywiódł tu resztę i narobił zamętu na wykopaliskach.$b$bProszę cię o jeszcze jedno, ostatnie zadanie, $N. Dopilnuj, żeby Sarltooth poniósł karę. A zważywszy na ciężar jego zbrodni, kara w tym wypadku oznacza śmierć! Przynieś mi jeden z jego szponów jako dowód, że nie żyje.', 'Ormer Żelaznowarkoczy na Wykopaliskach Whelgara chce, żebyś $gzabił:zabiła; Sarltootha i $gwrócił:wróciła; do niego z jednym z jego szponów.', '', 'Wróć do Ormera Żelaznowarkoczego na Wykopaliskach Whelgara na Bagniskach.', '', '', '', '', 0),
(299, 'koKR', 'Odkrywanie przeszłości', 'Tuż przed napaścią odkopałem dużą tablicę zwaną Kamieniem Goaz. Przetłumaczony tekst urywa się w 4 miejscach. Mowa w nim o „boskim planie” i „zgubnym proroctwie”.$b$bObawiam się, że kończy się nam czas. Jestem za stary, żeby zejść na dół i stawić czoła tym bestiom. Ale ty masz siłę.$b$bPrzeszukaj wykopaliska i odnajdź 4 brakujące fragmenty tablicy: Ados, Modr, Golm i Neru. Szukaj ich w starożytnych artefaktach albo tam, gdzie ziemia jest luźna. Przynieś mi je, żebym mógł zacząć zgłębiać tę tajemnicę!', 'Poszukiwacz Whelgar chce, żebyś $gprzeszukał:przeszukała; wykopaliska i $godnalazł:odnalazła; 4 brakujące fragmenty tablicy: Ados, Modr, Golm i Neru.', '', 'Wróć do poszukiwacza Whelgara na Wykopaliskach Whelgara na Bagniskach.', '', '', '', '', 0),
(303, 'koKR', 'Wojna z Czarnorytymi', 'Wojna szaleje i w kraju, i za granicą. Podczas gdy dzielni krasnoludzcy żołnierze oddają życie na dalekich ziemiach w imię Przymierza, nasze własne ziemie padają ofiarą niegodziwości Czarnorytych. Zrównali z ziemią Most Thandol. Wkrótce potem padło Dun Modr.$b$bMusisz zebrać siły i zepchnąć front. Jeśli zabijesz 10 krasnoludów Czarnorytych, 5 tunelarzy, 5 sabotażystów i 5 minierów, rezerwa może zdążyć dokończyć natarcie.$b$bA teraz pośpiesz się!', 'Motley Garmason w Dun Modr chce, żebyś $gzabił:zabiła; 10 krasnoludów Czarnorytych, 5 tunelarzy Czarnorytych, 5 sabotażystów Czarnorytych i 5 minierów Czarnorytych.', '', '', '', '', '', '', 0),
(304, 'koKR', 'Ponure zadanie', 'Wielu moich żołnierzy zginęło w bitwie o Dun Modr. Mój rodzony brat zginął, kiedy wysadzono zachodnie przęsło Mostu Thandol. Ano, Czarnoryci to diabelskie plemię. Z tego, co Roggo zdołał ustalić, tymi zbirami na Bagniskach dowodzi czarnoksiężnik Balgaras Plugawy. To straszny tchórz – posyła żołnierzy, żeby odwalali za niego robotę, a sam chowa się w obozie na Wzgórzu Złowrogiej Kuźni, na południowym wschodzie.$b$bJeśli znajdziesz tę bezkręgową gnidę, zabij go i przynieś mi jego ucho. Wynagrodzę cię, $N.', 'Zabij Balgarasa Plugawego i przynieś jego ucho Długowarkoczowi Ponuremu pod Dun Modr.', '', 'Wróć do Długowarkocza Ponurego w Dun Modr na Bagniskach.', '', '', '', '', 0),
(305, 'koKR', 'W poszukiwaniu ekipy wykopaliskowej', 'Och, to pewnie ty jesteś $gtym zwiadowcą, którego:tą zwiadowczynią, którą; obiecał przysłać Długowarkocz! Nie wyobrażasz sobie, jak się martwiłem.$b$bMoja żona, Merrin, przez ostatni miesiąc co tydzień przysyłała mi listy. Pracuje w ekipie wykopaliskowej Whelgara. Ale od jej ostatniego listu minęły prawie dwa tygodnie. Na pewno coś się stało!$b$bDługowarkocz mówił, że jeśli wkrótce nie dostaniemy wieści od ekipy, wyśle zwiadowcę, żeby sprawdził, co się dzieje. Zakładam, że to ty, $N. Odszukaj Merrin na wykopaliskach na wschodzie!', 'Tarrel Skałotkacz chce, żebyś $gudał:udała; się na wykopaliska i $godnalazł:odnalazła; Merrin Skałotkacz.', '', '', '', '', '', '', 0),
(306, 'koKR', 'W poszukiwaniu ekipy wykopaliskowej', 'To było straszne! Odkopywaliśmy rzadkie artefakty, kiedy zaczęliśmy natrafiać na te wielkie kości.$b$bZanim się zorientowaliśmy, co się dzieje, cętkowane raptory opanowały wykopaliska. Wielu straciło życie.$b$bOrmer – taki odważny! – ocalił poszukiwacza i mnie. Osłaniał nas, kiedy uciekaliśmy do kryjówki. Teraz jesteśmy tu uwięzieni, a cała nasza ciężka praca legła w gruzach.$b$bProszę, zanieś ten list mojemu kochanemu Tarrelowi. Wszystko mu wyjaśni.', 'Wróć z listem Merrin do Tarrela Skałotkacza w Przystani Menethilów na Bagniskach.', '', '', '', '', '', '', 0),
(462, 'koKR', '', 'Oprócz ciebie wysłaliśmy przez Algaz dwóch zwiadowców. Wrócił tylko jeden. Oto, czego się dowiedział:$B$BSmocze Paszcze wysłały jednego ze swoich poruczników, Ma\'ruka Smokołuskiego, żeby zebrał w Algaz bandę orków i odciął lądową drogę do Przystani Menethilów!$B$BMusimy to powstrzymać, i to zaraz. Zlikwiduj Ma\'ruka, a potem zamelduj się u Valstaga Żelaznoszczękiego w Przystani Menethilów.$B$BKwatera Ma\'ruka mieści się w małej jaskini, za stawem między drugim a trzecim tunelem Algaz. Do Menethil dojdziesz przez Algaz, a potem drogą na zachód.', 'Zabij Ma\'ruka Smokołuskiego.$B$BZamelduj się u Valstaga Żelaznoszczękiego w Przystani Menethilów.', '', 'Wróć do Valstaga Żelaznoszczękiego w Zatoce Baradina na Bagniskach.', '', '', '', '', 0),
(463, 'koKR', 'Strażnik Zieleni', '$GSłyszałeś:Słyszałaś; o Strażniku Zieleni? Chyba go nie szukasz, co? Jak tak, to masz nie po kolei w głowie, ale kimże ja jestem, żeby bronić $ggłupcowi:głupiej; iść na śmierć?$B$BJeśli naprawdę szukasz tej bestii, to podobno siedzi na moczarach, na wschód od drogi, tam, gdzie odbija do Dun Modr. Czai się tam wśród krokoliszków... i gorszych rzeczy!$B$BA pieniądze zostaw tutaj. Tam, dokąd idziesz, nie będą ci potrzebne... Chyba nie chcesz, żeby staremu Zieluchowi wyszczerbił się ząb na twoim złocie, kiedy przegryzie cię na pół, co?', 'Odnajdź Strażnika Zieleni.', '', '', '', '', '', '', 0),
(464, 'koKR', 'Sztandary wojenne', 'Orkowy klan Smoczych Paszcz został niemal doszczętnie wybity pod koniec Drugiej Wojny, kiedy orkowie stracili kontrolę nad swoimi czerwonymi smoczymi pupilami. Smoki nie pałały miłością do dawnych panów i zaciekle polowały na Smocze Paszcze. Nieliczni ocaleli uciekli z Grim Batol w góry na wschód od Wykopalisk Whelgara.$B$BTeraz odzyskali siły i rozbili obóz na północny wschód od Menethil.$B$BChcemy, żebyś $gzaatakował:zaatakowała; ten obóz. Zbierz ich sztandary wojenne i przynieś mi je jako dowód.', 'Przynieś 8 sztandarów wojennych Smoczych Paszcz kapitanowi Tęgopięściowi.', '', 'Wróć do kapitana Tęgopięścia w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(465, 'koKR', 'Gambit Nek\'rosha', 'Kiedy $gwalczyłeś:walczyłaś; ze Smoczymi Paszczami, poznaliśmy więcej ich planów.$B$BNek\'rosh zbudował katapulty i zamierza oblegać Menethil! A przez walki w Dun Algaz jesteśmy praktycznie odcięci od posiłków!$B$BMusisz zniszczyć te katapulty. Stoją w obozie Smoczych Paszcz.$B$BMasz, weź tę hubkę. Przebij się do katapult i podpal je.$B$BA kiedy już to zrobisz, znajdź i zabij Nek\'rosha. Musimy powalić tę bestię Smoczych Paszcz... i to ucinając jej łeb.', 'Zniszcz katapulty Smoczych Paszcz.', '', '', '', '', '', '', 0),
(469, 'koKR', 'Codzienna dostawa', 'Witaj, $gpodróżniku:podróżniczko;!$b$bNie idziesz przypadkiem w stronę Menethil? Jeśli nie, to radzę tam zajrzeć – to dobre miejsce, żeby zrobić zakupy, a nawet wypić kufelek i odsapnąć.$b$bA jeśli tak się składa, że idziesz w tamtą stronę, to może zaniesiesz ten pęk skór krokoliszka Jamesowi Halloranowi, garbarzowi?$b$bSam bym to zrobił, ale moja żona ma ostatnio humory, a ja wolałbym jak najdłużej odwlec spotkanie z nią.', 'Dostarcz pęk skór krokoliszka Jamesowi Halloranowi, garbarzowi w Przystani Menethilów.', '', '', '', '', '', '', 0),
(470, 'koKR', 'Grzebanie w szlamie', 'Podczas cotygodniowej wizyty w Grobowcu Żelaznobrodego zaatakowały mnie straszne, ociekające szlamy! Oczywiście wpadłam w panikę.$b$bRzuciłam w jeden z nich torbą, ale nic to nie dało! Szlam po prostu ją wessał... Na szczęście dzięki temu zdążyłam uciec.$b$bZła wiadomość jest taka, że bardzo potrzebuję tego, co było w torbie!$b$bNie wiem, w który szlam rzuciłam torbą – wszystkie wyglądały tak samo! Grobowiec Żelaznobrodego jest na północny wschód stąd, niedaleko Dun Modr. Stokrotne dzięki!', 'Jeden ze szlamów w Grobowcu Żelaznobrodego ma torbę Sidy. Odzyskaj ją i zanieś Sidzie do Przystani Menethilów.', '', 'Wróć do Sidy w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(471, 'koKR', 'Obowiązki ucznia', 'Wysłałem ucznia na moczary, żeby oskórował kilka naszych słynnych olbrzymich krokoliszków z Bagnisk. Kiedy nie wrócił, poszedłem go szukać... Powiedzmy, że nie był to przyjemny widok.$b$bAkuszerka mówi, że może się wyliże, ale ja tymczasem wciąż potrzebuję skór!$b$b...Jeśli chcesz ubić jeszcze kilka tych bydlaków, nie będę miał nic przeciwko – po tym, co zrobiły. Krokoliszki znajdziesz na północy, w górę wybrzeża, za lepiankami murloków.', 'Zbierz 6 skór olbrzymiego krokoliszka i przynieś je Jamesowi Halloranowi w Przystani Menethilów.', '', 'Wróć do Jamesa Hallorana w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(472, 'koKR', 'Upadek Dun Modr', 'Dun Modr padło łupem Czarnorytych!$b$bMoje rany są ciężkie, $N. Większość regimentu zginęła! Czarnorycka hołota napadła na nas, zanim zdążyliśmy się przegrupować po zasadzce na Moście Thandol.$b$bNasz dowódca, Długowarkocz, zatrąbił do odwrotu. Kiedy opuszczaliśmy miasto, trafił mnie w plecy zabłąkany topór. Wszystko zrobiło się czarne.$b$bOcknąłem się tutaj, w Menethil, ale boję się o moich towarzyszy broni. Wciąż tli się we mnie nadzieja. Może Długowarkocz jeszcze żyje! Sprawdź, czy znajdziesz go w okolicach Dun Modr!', 'Poszukaj Długowarkocza w okolicach Dun Modr.', '', '', '', '', '', '', 0),
(473, 'koKR', 'Zamelduj się u kapitana Tęgopięścia', '$N. Orkowy klan Smoczych Paszcz pokazuje swoją siłę nie tylko w Algaz. Kapitan Tęgopięść chce pomówić z tymi, którzy są gotowi pomóc w walce z tymi orkami. Jest w twierdzy, w sali wojennej.', 'Porozmawiaj z kapitanem Tęgopięściem.', '', '', '', '', '', '', 0),
(474, 'koKR', 'Pokonaj Nek\'rosha', 'Teraz, gdy katapulty spłonęły, znajdź i zabij wodza Nek\'rosha.', 'Zabij wodza Nek\'rosha.$B$BPrzynieś głowę Nek\'rosha kapitanowi Tęgopięściowi.', '', 'Wróć do kapitana Tęgopięścia w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(484, 'koKR', 'Skóry młodych krokoliszków', 'Jestem James Halloran, garbarz. Na moje wyprawione skóry krokoliszków jest popyt wszędzie – statki wiozą je do portów na całym świecie.$b$b$GPoznałeś:Poznałaś; Einara? To jeden z myśliwych, którzy przynoszą mi skóry krokoliszków.$b$bBrakuje mi trochę delikatniejszych skór, jakie zdejmuje się z młodych krokoliszków.$b$bSkoro mam ich mało, zapłacę ci najlepszą cenę za porcję takich skór. Młode krokoliszki znajdziesz na moczarach tuż za miastem.', 'Zdobądź 4 skóry młodego krokoliszka dla Jamesa Hallorana w Przystani Menethilów.', '', 'Wróć do Jamesa Hallorana w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(631, 'koKR', 'Most Thandol', 'Przez wzgórza przetoczył się potężny wybuch. Okropność, mówię ci!$b$bDobrzy żołnierze zginęli w obronie Mostu Thandol. Długowarkocz mówi, że zanim to wszystko się skończy, pomścimy się na Czarnorytych.$b$bAle jesteśmy w nie lada tarapatach, a posiłków ani widu, ani słychu. Długowarkocz wysłał Starego Rustlocke\'a na zwiad do wschodniego mostu, żeby sprawdził, czy da się go utrzymać.$b$bTo było kilka dni temu. Z Dun Modr w oblężeniu nie mamy ludzi, żeby go szukać.$b$bMoże ty go znajdziesz...', 'Rhag Garmason chce, żebyś $godnalazł:odnalazła; Starego Rustlocke\'a.', '', '', '', '', '', '', 0),
(632, 'koKR', 'Most Thandol', 'Wygląda na to, że biedny Stary Rustlocke wpadł w zasadzkę Czarnorytych. Obok jego zaciśniętej pięści zauważasz pergamin.$b$bPrzekaż ponure wieści Rhagowi Garmasonowi i pokaż mu, co $gznalazłeś:znalazłaś;.', 'Zamelduj się u Rhaga Garmasona w Dun Modr na Bagniskach i pokaż mu pergamin, który $gznalazłeś:znalazłaś; przy zwłokach Rustlocke\'a.', '', '', '', '', '', '', 0),
(633, 'koKR', 'Most Thandol', 'Na niebiosa, nie! Biedny Rustlocke. Prawdziwa tragedia.$b$bNie możemy pozwolić, by jego śmierć poszła na marne. Z pergaminu, który $gznalazłeś:znalazłaś;, wynika, że Kam Głębogniew, mózg pierwszego ataku, kazał ukryć skład materiałów wybuchowych tuż za Mostem Thandol, na Wyżynach Aratorskich.$b$bJeśli te materiały dotrą do mostu, nasz główny szlak zaopatrzenia na północ zostanie przerwany! Skład trzeba zniszczyć, $n! Wróć do mnie, kiedy wykonasz zadanie.$b$bJesteś naszą jedyną nadzieją.', 'Zniszcz skład materiałów wybuchowych.', '', 'Wróć do Rhaga Garmasona w Dun Modr na Bagniskach.', 'Skład materiałów wybuchowych zniszczony', '', '', '', 0),
(634, 'koKR', 'Prośba do Przymierza', 'Proszę cię o jeszcze jedną małą przysługę, $N. Czekamy na rezerwy z Żelaznej Kuźni. Roggo wie jednak o obozie Przymierza na północy, w Punkcie Schronienia na Wyżynach Aratorskich.$b$bUdaj się tam i odszukaj kapitan Nials. Zapytaj zacną panią kapitan, czy Przymierze może nam użyczyć trochę żołnierzy, żebyśmy odbili Dun Modr i Most Thandol.', 'Odszukaj kapitan Nials w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(647, 'koKR', 'Bimber MacKreela', 'Wczoraj wieczorem nieźle się uraczyłem starym dobrym bimbrem! Długowarkocz urwałby mi łeb, gdyby wiedział, że zasnąłem na warcie.$b$bŁeb mi pęka jak diabli. Miałem wrażenie, jakby nad głową przetoczyła mi się cała brygada machin oblężniczych – ależ dudniło.$b$bO rety, która to godzina! Obiecałem mistrzowi piwowarskiemu Bilgerowi z Południowego Brzegu, że spłacę dług, przysyłając mu trochę bimbru.$b$bA zostało tylko 15 minut, zanim się spóźnię! Zanieś mu tę partię, dobrze? I pośpiesz się!', 'Zanieś bimber MacKreela mistrzowi piwowarskiemu Bilgerowi w Południowym Brzegu.', '', '', '', '', '', '', 0),
(1132, 'koKR', 'Fiora Długie Uszy', 'Och, znów być na morzu! Czuć pocałunek wiatru i dać się kołysać falom jak niegdyś błogosławionej matce!$B$BOch, gdybym miał twoje szczęście, $N, bo w twojej przyszłości widzę morze!$B$BMoją robotą jest opowiadać chętnym duszom o Kalimdorze, krainie możliwości! Jeśli chcesz spróbować szczęścia za morzem, wsiądź tu na statek do uroczego portu Auberdine. Pomów tam z moją wspólniczką, elfką Fiorą Długie Uszy.$B$BTo ona rozpocznie twoją przygodę w Kalimdorze!', 'Porozmawiaj z Fiorą Długie Uszy w dokach Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', '', '', 0),
(1302, 'koKR', '', 'Mój brat James wyruszył z lady Proudmoore za morze. Ostatnio słyszałem, że walki tam przycichły, a James otwierał gdzieś na kontynencie karczmę. Gdziekolwiek jest, na pewno dobrze mu się wiedzie. Diabelnie dobrze gotował.$b$bOd jakiegoś czasu nie mam od niego wieści – pewnie jest zbyt zajęty karczmą – ale urzędnik w Theramore pewnie wskaże ci drogę. Szukaj go na najwyższym piętrze twierdzy w środku miasta. Jak ona się nazywa... Cytadela Przyczółku, tak jest.', 'Porozmawiaj z urzędnikiem Lendrym w Cytadeli Przyczółku w Theramore.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(275, 'koKR', 'Twój trud przyniósł tej ziemi ukojenie, dlatego obdarzę cię nagrodą.', 0),
(276, 'koKR', 'Przetrzebiając gnole, $gzadbałeś:zadbałaś; o zdrowie Bagnisk. Choć twój lud nieraz wystawiał moją wiarę na próbę, być może uda się ją jeszcze odbudować.', 0),
(277, 'koKR', '...dziękuję. Roztrzaskam te krzemienie i rzucę je w morze, by już nigdy nie posłużyły do palenia żywego drewna.', 0),
(279, 'koKR', 'Ach, dobra robota, $N.$b$bPrzyjmij to jako zapłatę za wypełnienie kontraktu z Marynarką Handlową.', 0),
(281, 'koKR', 'Skrzynia jest pokryta śladami pazurów i zaciekami od wody. Po podważeniu wieka widać rozmokłą, zbutwiałą słomę, jakby trzymano w niej coś cennego. Przeszukujesz słomę...$B$B...i znajdujesz naręcze czerwonych butelek.', 0),
(284, 'koKR', 'Ta beczka jest prawie nietknięta. Podważasz wieko...$B$B...i uderza cię ostra woń sera. Trochę zamókł, ale wciąż jest smaczny!', 0),
(285, 'koKR', 'Ta beczka jest do połowy zakopana w błocie i trawie...', 0),
(286, 'koKR', 'Kapitan „Ślepej Księżniczki” odetchnie z ulgą, gdy usłyszy, że ten cenny ładunek się odnalazł. $GZasłużyłeś:Zasłużyłaś; na tę zapłatę za swoje usługi.$B$BDobrze widzieć kogoś tak rzetelnego jak ty, zwłaszcza w tak ciężkich czasach.', 0),
(288, 'koKR', 'Ach! To mi było potrzebne – od razu język się rozwiązuje. Dzięki, $gkolego:koleżanko;!', 0),
(289, 'koKR', 'Dziękuję ci, $N. Przyjmij też wdzięczność moich przeklętych braci.', 0),
(290, 'koKR', 'Klucz jest zardzewiały, ale gładko pasuje do zamka.', 0),
(292, 'koKR', 'Oko Paletha? Niesamowite! Hmm... coś jest nie tak z tym egzemplarzem. $GZnalazłeś:Znalazłaś; je na jednym z tych wraków? No to wszystko jasne! Ale... nie wiedziałem, że Trzecia Flota wiozła takie oko...$B$BNic dziwnego, że Fitzsimmons tak się trząsł ze strachu. Z przeklętym okiem Paletha nie ma żartów.', 0),
(294, 'koKR', 'Zabijanie to brudna robota, ale $gspisałeś:spisałaś; się dobrze, $N. Gdybym nie musiał zostać przy poszukiwaczu i Merrin, sam bym tam na dole przelewał krew ramię w ramię z tobą.', 0),
(295, 'koKR', 'Kawał porządnej roboty z tymi raptorami, $N!', 0),
(296, 'koKR', 'Dziękuję ci, $N. Twój trud nie zostanie zapomniany. Na tych wykopaliskach zginęło wielu niewinnych krasnoludów, którzy po prostu wykonywali swoją pracę. Zemsta, jaką $gwymierzyłeś:wymierzyłaś; tym podłym stworom, powinna je nauczyć, żeby dwa razy się zastanowiły, zanim znów napadną na poddanych króla Magniego.', 0),
(299, 'koKR', 'Ach, Kamień Goaz jest kompletny! Świetna robota, $N. Doprawdy świetna. Teraz mogę kontynuować żmudne tłumaczenie tego pisma tytanów. Już odczytuję nowe słowa! Hmm... tu jest napisane: „Przedwieczni... Skuci pod ziemią”. To początek czegoś wielkiego.', 0),
(303, 'koKR', 'Dobrze $gwykonałeś:wykonałaś; rozkazy, $N. $GDowiodłeś:Dowiodłaś;, że jesteś $gdzielnym żołnierzem:dzielną wojowniczką; i $gwiernym sługą:wierną sługą; króla Magniego, i za to ci salutuję! Dzięki naciskowi, jaki $gwywarłeś:wywarłaś; na obóz Czarnorytych, mamy teraz szansę przegnać ich z naszych ziem na dobre... gdyby tylko ta przeklęta rezerwa raczyła się zjawić...', 0),
(304, 'koKR', 'Balgaras Plugawy wreszcie nie żyje. Jego śmierć nie wróci życia wielu niewinnym krasnoludom, które niepotrzebnie zginęły z jego ręki, ale przyniesie spokój tym, którzy przeżyli. Bez Balgarasa z resztą czarnoryckiej hołoty łatwo sobie poradzimy. Teraz musimy ich wybić, zanim przyślą w te strony nowego przywódcę.$B$BDobrze się $gspisałeś:spisałaś;, $N.', 0),
(305, 'koKR', 'Och, dzięki niebiosom, że jesteś!', 0),
(306, 'koKR', 'Straszne wieści! Przynajmniej troje z nich przeżyło. Ale kiedy skończy się to zabijanie? Tęsknię za dniem, w którym poddani króla Magniego będą mogli żyć bez strachu.', 0),
(463, 'koKR', 'Korzenie i paprocie dobrze o tobie mówią, mała istoto. Mam wiele imion, lecz odpowiadam tylko na nieliczne. Ty możesz nazywać mnie Rethiel.$B$BA teraz słuchaj... bo te ziemie płaczą od jątrzących się ran, a ja powierzam ci ich uleczenie.', 0),
(464, 'koKR', 'Dobrze $gwalczyłeś:walczyłaś;, $N. Smocze Paszcze bez smoków nie są już takim zagrożeniem jak kiedyś, ale wciąż to zaciekli przeciwnicy.$b$bSmoczym Paszczom przewodzi Nek\'rosh, syn Nekrosa, który przed laty stał na czele klanu. Nekros ujarzmił czerwone smoki potężną magią, ale gdy ta magia go zawiodła... smoki nie były zadowolone.$b$bNekros zginął, a jego syn poprzysiągł zemstę smokom, które zabiły jego ojca.', 0),
(465, 'koKR', 'Kładziesz na katapulcie trochę hubki i krzesasz na nią iskrę.$B$BBuchają płomienie i szybko się rozprzestrzeniają!', 0),
(469, 'koKR', 'Hmm, to od Einara, tak? Już prawie tydzień nie przyniósł mi skór osobiście. Pewnie znowu jakieś niesnaski z żoną!$b$bMoże poślę kiedyś żonę, żeby pogadała z Sidą...', 0),
(470, 'koKR', 'Och, dziękuję, $N! Bałam się, że przepadła na dobre!$B$B<Szybko wysypuje na ziemię zawartość pokrytej szlamem torby, a potem ją zgarnia.>$B$BHm, mnie to już na nic, ale jak to opłuczesz, na pewno ci się przyda.', 0),
(471, 'koKR', 'Hmm... Nie masz przypadkiem ochoty zostać $gmoim uczniem:moją uczennicą;?$b$bHa! Nie, żartuję. Po pierwsze, jesteś na to o wiele za $gstary:stara;. A poza tym, sądząc po wyglądzie, masz w życiu inne ambicje. Tak czy inaczej, $gzdobyłeś:zdobyłaś; świetne skóry i zrobię z nich dobry użytek.', 0),
(472, 'koKR', 'Cóż to za $gśmiałek:śmiałkini; przynosi wieści z Menethil? Ach, $N, tak cię zwą.$b$bNiesiesz nadzieję tam, gdzie już jej nie było. To dobra nowina, że młody Harlo przeżył. W czasie ucieczki odniósł ciężką ranę. Ledwie zdążyliśmy wsadzić go na grzbiet jedynego wierzchowca, jaki ocalał w regimencie, i odesłać w drogę.$b$bAle teraz jesteśmy w niebezpiecznym położeniu. Dun Modr padło, a z naszego wielkiego regimentu został ledwie cień.', 0),
(473, 'koKR', '$N. Valstag opowiedział mi o twoich sukcesach w walce z orkami Smoczych Paszcz w Dun Algaz. Wiele jesteś $gwart:warta;.$b$bMam dla ciebie zadanie.', 0),
(474, 'koKR', 'Tęgo się $gspisałeś:spisałaś;, $N. $GZadałeś:Zadałaś; orkowemu klanowi Smoczych Paszcz dotkliwy cios. Mogą się już nigdy nie podnieść. A zniszczenie katapult zapewniło Przystani Menethilów bezpieczeństwo.$B$BZasługujesz na uznanie, a królestwo Żelaznej Kuźni nagradza tych, którzy dobrze mu służą.', 0),
(484, 'koKR', 'Kawał dobrej roboty, $N. Te skóry są znakomitej jakości. Muszę je jak najszybciej oddać do wyprawienia. Och, ale zanim się za to zabiorę, mam jeszcze inną robotę, z którą chyba sobie poradzisz.', 0),
(631, 'koKR', 'Przeszukujesz drobne krasnoludzkie zwłoki. Na hełmie wyraźnie widać wygrawerowane imię: Ebenezer Rustlocke.', 0),
(632, 'koKR', 'Ojej, złe to wieści...', 0),
(633, 'koKR', 'Ocalały most jest uratowany! $GOddałeś:Oddałaś; wielką przysługę królowi Magniemu i ludowi Khaz Modan.$B$BGdybyśmy tylko zdołali wytrwać, aż zjawią się posiłki...', 0),
(634, 'koKR', 'Składam wyrazy współczucia Długowarkoczowi i jego dzielnym żołnierzom. Wieść o tragedii na Moście Thandol i upadku Dun Modr leży mi ciężko na sercu.$b$bAle Stromgard upadł! Dlatego jesteśmy tu, w Punkcie Schronienia. Sami musimy odbić nasze własne wielkie miasto.$b$bHonor i obowiązek każą nam nie opuszczać Wyżyn, dopóki nad Stromgardem znów nie załopocze potężny sztandar króla. Dam znać Długowarkoczowi, że musi radzić sobie sam...', 0),
(647, 'koKR', 'Ach, nie ma to jak bimber Zamglonego MacKreela na rozgrzewkę w chłodny dzień! A ja już myślałem, że ten mały łobuz znowu zalega z rachunkami. Dziękuję, $gprzyjacielu:przyjaciółko;! Stokrotne dzięki!', 0),
(1132, 'koKR', 'Dzień dobry! Przysłał cię pan Flint z Przystani Menethilów? Pan Flint świetnie zna się na ludziach. Skoro cię przysłał, na pewno twoje miejsce jest tu, w Kalimdorze!', 0),
(1302, 'koKR', 'James Hyal, James Hyal... Czemu to nazwisko brzmi tak znajomo?$b$bNo tak! Sprawa karczmy „Cienisty Wypoczynek”. Jeśli wiesz coś o tym, co się tam stało, radzę ci pomówić z kapitanem Vimesem. To on prowadzi śledztwo.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(275, 'koKR', 'Bagniska wciąż płaczą, a pełzacze trzęsawisk wciąż szaleją. Wróć do mnie, gdy wypełnisz zadanie.', 0),
(276, 'koKR', 'Twoje zadanie wciąż czeka, $N.', 0),
(277, 'koKR', 'Masz narzędzia, którymi gnole rozniecają ogień?', 0),
(279, 'koKR', 'Nasi kupcy nie będą bezpieczni, dopóki nie pozbędziemy się Żarłoka i tych murloków.', 0),
(286, 'koKR', 'Masz posążek?', 0),
(288, 'koKR', 'Och, jak mi się chce pić! Nie postawisz kufelka biednemu, żałosnemu durniowi?', 0),
(289, 'koKR', 'W snach słyszę czasem jęki moich zgubionych braci! Proszę, $gdobry panie:dobra pani;, uwolnij ich z okowów i ucisz ich krzyki.', 0),
(290, 'koKR', 'Ta skrzynia jest solidnie zamknięta.', 0),
(292, 'koKR', 'Ten pijaczyna Fitzsimmons przysłał cię do mnie? No to możesz mu przekazać, że nie mam piwa na zbyciu. Niech żebrze u kogoś innego!', 0),
(294, 'koKR', 'Zabij 10 cętkowanych raptorów i 10 cętkowanych skrzekaczy, $N. Moi towarzysze nie zasłużyli na taki los. Czas wyrównać rachunki.', 0),
(295, 'koKR', 'Chcę, żeby te cętkowane kosopazury i cętkowane brzytwopaszcze zapłaciły za to, co zrobiły. $GZabiłeś:Zabiłaś; już po 10 z każdego rodzaju?', 0),
(296, 'koKR', 'Czy Sarltooth nie żyje? $GPomściłeś:Pomściłaś; pamięć poległych?', 0),
(299, 'koKR', 'Masz już te cztery fragmenty, $N? Ados, Modr, Golm i Neru...', 0),
(303, 'koKR', 'Roggo nie może się skontaktować z oddziałami rezerwy. Musimy przycisnąć ten obóz Czarnorytych, $N. A teraz wracaj tam i pełnij służbę dla króla Magniego!', 0),
(304, 'koKR', 'Udało ci się już wytropić Balgarasa Plugawego, $N? Od dłuższego czasu nam się wymyka.', 0),
(306, 'koKR', 'Udało ci się znaleźć Merrin? Przekazała jakąś wiadomość?', 0),
(464, 'koKR', '$GZaatakowałeś:Zaatakowałaś; obóz Smoczych Paszcz?', 0),
(465, 'koKR', 'Przed tobą pierwsza katapulta. Podpalisz ją?', 0),
(469, 'koKR', 'Witaj, $N. Może skusisz się na parę butów? Albo na świeżo wyprawione skóry?', 0),
(470, 'koKR', '$GZnalazłeś:Znalazłaś; moją torbę?', 0),
(471, 'koKR', 'Mój uczeń jest dla mnie jak syn. Ciężko mu będzie żyć z jedną nogą.$b$bAch, $N, jak idzie? Masz moje skóry?', 0),
(474, 'koKR', '$GZabiłeś:Zabiłaś; Nek\'rosha?', 0),
(484, 'koKR', '$N, tak? Masz moje skóry?', 0),
(632, 'koKR', 'Jakieś wieści o Starym Rustlocke\'u, $N?', 0),
(633, 'koKR', 'Skład materiałów wybuchowych musi zostać zniszczony!', 0),
(647, 'koKR', 'Co dobrego słychać?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(1071, 0, 'koKR', 'Jeśli czas czegoś mnie nauczył, to tego, że żadne zadanie nie jest nudne. Obrona Mostu Thandol miała być łatwą robotą. Ale skoro główne siły armii walczą u boku Przymierza, tu nas przytłoczono i Dun Modr padło.', 0),
(1239, 0, 'koKR', 'Jeśli zniesiesz opowieści, od których zatrzeszczą ci wręgi i przemokną gacie, to weź sobie coś do picia i przysiądź na chwilę...', 0),
(2094, 0, 'koKR', 'Witaj, $N. Mam teraz mały kłopot – kończą mi się skóry.', 0),
(2700, 0, 'koKR', 'My, w Punkcie Schronienia, trzymamy jeden z nielicznych skrawków ziemi Stromgardu, jakie zostały na Wyżynach Aratorskich. I tracimy grunt...$B$BJeśli masz dla mnie wieści, mam nadzieję, że dobre.', 0);
INSERT INTO `creature_template_locale` (`entry`, `locale`, `Name`, `Title`, `VerifiedBuild`) VALUES
