INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(92, 'koKR', 'Mój najdroższy Tarrelu,\n\nwybacz pośpiech, z jakim piszę ten list, ale czas to luksus, na który nas nie stać.\n\nEkipa wykopaliskowa robiła znaczne postępy w odkopywaniu ważnych artefaktów tytanów. Zaczęliśmy jednak natrafiać na inne starożytne przedmioty, a konkretnie na wielkie kości.', 0),
(93, 'koKR', 'Niedługo po odkopaniu kości napadły na nas raptory. Oddział z regimentu Długowarkocza walczył dzielnie, ale w końcu uległ przewadze. Zginęli niemal wszyscy. Przeżyło tylko troje z nas. Robotnik imieniem Ormer Żelaznowarkoczy wykazał się prawdziwym bohaterstwem – to dzięki niemu ja i poszukiwacz Whelgar jesteśmy bezpieczni.', 0),
(94, 'koKR', 'Schroniliśmy się w osłoniętej jaskini, na razie chyba poza zasięgiem niebezpieczeństwa. Jesteśmy tu jednak uwięzieni, dopóki ktoś nie przyśle oddziału, który rozprawi się z raptorami. Whelgar próbuje dalej pracować, ale podejrzewam, że wciąż jest mocno przestraszony. Tak wygląda nasze położenie, Tarrelu. Proszę, nakłoń Długowarkocza, żeby natychmiast zebrał oddział ratunkowy.\n\nMoja miłość do ciebie nie słabnie, nawet w tych ciężkich chwilach.\n\n– Merrin', 0),
(316, 'koKR', 'Niezdary i durnie!$B$BWedług mojego planu oba mosty miały zostać zniszczone jednocześnie. A co wy robicie, tępe zbiry? Odwalacie tylko połowę roboty i zdradzacie nasze zamiary całemu Przymierzu. Durnie, powiadam!$B$BMacie jedną szansę, żeby naprawić swoje błędy. Na Wyżynach Aratorskich, niedaleko mostu, mamy zapasowy skład materiałów wybuchowych.$B$BDokończcie robotę, jeśli cenicie swoje marne życie!$B$B– Kam Głębogniew', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(318, 'koKR', 'Burzliwe dziś morze. Duchy morskie pewnie się niepokoją... hep!', '', 0),
(319, 'koKR', 'Raz widziałem morskiego olbrzyma. Wolałbym go więcej nie oglądać. Bek!', '', 0),
(320, 'koKR', 'Poszedłbym przetrzebić trochę tych gnoli, ale ta noga widziała lepsze dni i boję się, że skończyłbym w grobie.', '', 0),
(321, 'koKR', 'Uważaj, gdzie stąpasz. Niejeden poszukiwacz przygód nie wrócił z moczarów. Hep!', '', 0),
(397, 'koKR', 'Hyyyp... Hyyyp... Bueeeee!', '', 0),
(449, 'koKR', '$n! $GZdrajco:Zdrajczyni; Ragnarosa!', '', 0),
(450, 'koKR', 'Czarnoryci odzyskają ziemie, które im się należą!', '', 0),
(451, 'koKR', 'Głupcze! Nie masz szans ze sługami Ragnarosa!', '', 0),
(452, 'koKR', 'Taki nędzny robak jak ty, $n, nie ma prawa chodzić po tych ziemiach!', '', 0),
(453, 'koKR', '$n! Szykuj się na swoją zgubę!', '', 0),
(454, 'koKR', 'Cóż to za $gsłabeusz:słabeuszka; śmie rzucać wyzwanie mojej potędze? Giń, głupcze!', '', 0),
(455, 'koKR', 'Ta ziemia należy do Czarnorytych. Szykuj się na tamten świat, $N!', '', 0),
(456, 'koKR', 'Jestem Balgaras Plugawy. A ty, $n, zaraz obrócisz się w popiół i pył.', '', 0),
(552, 'koKR', 'Jestem przeklęty! Najpierw tonie mój statek, a teraz... skończył mi się miód!', '', 0),
(553, 'koKR', 'Bodajbyś sczezł, Halyndorze! Zaprowadziłeś nas na zgubę!', '', 0),
(554, 'koKR', 'Nie zwracaj uwagi na mnie ani na mój zapach... bo ja na pewno nie zwracam!', '', 0),
(556, 'koKR', 'Ach, piękna Przystań Menethilów, z najlepszym miodem po tej stronie Żelaznej Kuźni.', '', 0),
(557, 'koKR', 'Och, bracia moi! Obyście zaznali spokoju w wodnych grobach!', '', 0),
(790, 'koKR', 'Coś mi się zdaje, że już bardzo dawno nikt mnie nie zluzował na posterunku.', '', 0),
(791, 'koKR', 'No i proszę, tak to jest, jak się zaśpi!', '', 0),
(873, 'koKR', '', '%s zaczyna przeglądać odznaki poległych obrońców Stromgardu...', 0),
(874, 'koKR', '', 'Szeregowi Marcus, Tremane, Osgood, Lampret...', 0),
(875, 'koKR', '', 'Szeregowi Fontane, MacDugal, Wilcott...', 0),
